"""
ClickUp task generator agent.

This module defines the ClickUpTaskGeneratorFromBacklogAgent, responsible for generating
ClickUp tasks from a backlog using an LLM. It transforms unstructured sprint
backlog content into structured domain tasks compatible with ClickUp workflow.
"""
import asyncio
import logging
import json
from typing import List, Dict

from backend.src.domain.entities.generated_tasks.generated_task_from_backlog import GeneratedTaskFromBacklog, \
    GeneratedTaskListFromBacklog
from backend.src.domain.entities.sprint.sprint import Sprint, UserStorySprint
from backend.src.domain.ports.services.prompt_loading.i_prompt_loader import IPromptLoader
from backend.src.domain.ports.services.task_generation_from_backlog.i_task_generator_from_backlog import ITaskGeneratorFromBacklog
from backend.src.infrastructure.external.shared.agents.base_agent import BaseAgent


logger = logging.getLogger(__name__)


class ClickUpTaskGeneratorFromBacklogAgent(BaseAgent[GeneratedTaskListFromBacklog], ITaskGeneratorFromBacklog):
    """
    LLM-based implementation of ITaskGenerator.

    This agent is responsible for:
    - Generating ClickUp tasks from a backlog
    - Mapping unstructured text into structured task entities
    - Aligning tasks with available folders, statuses, and priorities
    """

    def __init__(self, prompt_loader: IPromptLoader):
        """
        Initialize the ClickUpTaskGeneratorFromBacklogAgent.

        Args:
            prompt_loader (IPromptLoader): Service responsible for loading
                prompt templates used by the agent during LLM interactions.
        """
        super().__init__(prompt_loader)

    async def generate_tasks(
        self,
        sprint_backlog: Sprint,
        locations_priorities: Dict[str, Dict[str, List[str]]]
    ) -> List[GeneratedTaskFromBacklog]:
        """
        Generate ClickUp tasks from a backlog using an LLM.

        This method:
        - Sends the backlog and workspace structure to the LLM
        - Uses prompt templates to guide structured task generation
        - Parses the LLM response into domain task objects

        Args:
            sprint_backlog: sprint backlog content.
            locations_priorities: Mapping of locations to available priorities.

        Returns:
            List[GeneratedTask]: List of structured tasks generated by the LLM.

        Raises:
            LLMNetworkException: If a network error occurs while contacting the LLM.
            LLMApiException: If the LLM API returns an error response.
            LLMParsingException: If the LLM response cannot be parsed correctly.
        """
        logger.info("Starting task generation process from backlog.")

        if locations_priorities:
            locations_text = json.dumps(locations_priorities, ensure_ascii=False, indent=2)
        else:
            locations_text = "No locations available."

        context = ClickUpTaskGeneratorFromBacklogAgent._build_context(sprint_backlog)

        tasks_nested = await asyncio.gather(*[
            self._generate_tasks_from_user_story(locations_text, context, us)
            for us in sprint_backlog.user_stories
        ])

        tasks_flat = [task for tasks in tasks_nested for task in tasks]

        if not tasks_flat:
            logger.warning("No tasks extracted from backlog.")
            return []

        logger.info(
            "Task generating from backlog completed successfully: %d task(s) generated.",
            len(tasks_flat)
        )

        return tasks_flat

    def _generate_tasks_from_user_story(
        self,
        locations_text: str,
        context: str,
        user_story: UserStorySprint
    ) -> List[GeneratedTaskFromBacklog]:
        parsed: GeneratedTaskListFromBacklog = self._call_llm(
            agent_name="ClickUpTaskGeneratorFromBacklogAgent",
            folder_name="task_generation_from_backlog",
            prompt_name="clickup_task_generator_agent",
            variables={
                "locations_text": locations_text,
                "context": context,
                "user_story": ClickUpTaskGeneratorFromBacklogAgent._format_user_story(user_story),
            },
            response_format=GeneratedTaskListFromBacklog,
        )

        if not parsed or not parsed.tasks:
            return []

        return parsed.tasks

    @staticmethod
    def _format_user_story(user_story: UserStorySprint) -> str:
        lines = [
            f"User Story: {user_story.title}",
            f"Description: {user_story.description}",
            ""
        ]

        for task_estimate in user_story.tasks:
            task = task_estimate.task
            lines.append(f"  - Task: {task.title}")
            lines.append(f"  Description: {task.description}")
            lines.append(f"  Estimated Hours: {task_estimate.estimated_hours}h")
            lines.append("")

        return "\n".join(lines)

    @staticmethod
    def _build_context(backlog: Sprint) -> str:
        lines = [
            f"Sprint: {backlog.name}",
            f"Goal: {backlog.goal}",
            f"Total Estimated Hours: {backlog.total_estimated_hours}h",
            ""
        ]

        for us_sprint in backlog.user_stories:
            us = us_sprint.user_story
            lines.append(f"  User Story: {us.title}")
            lines.append(f"  Description: {us.description}")
            lines.append("")
        return "\n".join(lines)